   "id": "z920262bf",
   "sez": "mondo",
   "titolo": "Francia, a processo tre poliziotti per il pestaggio del produttore Michel Zecler",
   "orig": "French police officers face trial over beating of black man they accused of not wearing Covid face mask",
   "lead": "Tre agenti di polizia francesi compariranno a processo con l'accusa di aver percosso il produttore discografico Michel Zecler nel 2020 a Parigi, giustificando inizialmente l'intervento con il mancato uso della mascherina protettiva durante la pandemia di Covid-19. L'aggressione all'uomo, che oggi ha 47 anni, scatenò un'ondata di sdegno nell'opinione pubblica sul tema della violenza da parte delle forze dell'ordine, sollevando un aspro dibattito sulla natura sistemica degli abusi e rappresentando un raro caso giunto al vaglio giudiziario. Lo riferisce The Guardian.",
   "more": [
    "Il caso di Michel Zecler suscitò forti polemiche in Francia anche per la presenza di riprese di videosorveglianza che smentirono la versione iniziale fornita dagli agenti. L'episodio ha alimentato manifestazioni contro le proposte di legge che miravano a limitare la diffusione di immagini delle forze dell'ordine durante gli interventi pubblici."
   ],
