   "id": "zdf3107c0",
   "sez": "mondo",
   "titolo": "Ondata di proteste giovanili contro l'autoritarismo in diversi Paesi del mondo",
   "orig": "‘A global political awakening’: how gen Z protests are sweeping the world",
   "lead": "Dalla Serbia al Bangladesh, passando per Brasile, India e Francia, i giovani della generazione Z si stanno mobilitando contro l'autoritarismo e ridisegnando gli equilibri politici globali. In Brasile milioni di ragazzi hanno manifestato online condividendo video e contenuti grafici, mentre in Serbia gli attivisti hanno percorso l'Europa in bicicletta e corso ultramaratone per dare visibilità alle proprie rivendicazioni durante le campagne elettorali. Queste proteste testimoniano un risveglio politico diffuso attraverso forme di espressione e di dissenso del tutto inedite. Lo riferisce The Guardian.",
   "more": [
    "Le mobilitazioni della generazione Z combinano l'attivismo digitale sui social network con manifestazioni creative e forme di protesta diretta. I giovani manifestanti denunciano corruzione, restrizioni democratiche e disuguaglianze economiche, riuscendo spesso a catalizzare il malcontento popolare e a condizionare l'agenda politica tradizionale nei propri Paesi."
   ],
