   "id": "zc228f954",
   "sez": "prima",
   "titolo": "Crédit Agricole propone a Banco BPM una fusione per creare il terzo polo bancario",
   "orig": "Crédit agricole propone fusione con BPM",
   "lead": "Il gruppo bancario francese Crédit Agricole ha avanzato una proposta formale a Banco BPM per una fusione industriale con la propria filiale italiana, definendo l'operazione un'estensione amichevole della loro collaborazione storica. Il progetto, che prevede la distribuzione di un dividendo straordinario da un miliardo di euro senza il lancio di un'Opa, lascerebbe Giuseppe Castagna nel ruolo di amministratore delegato. Se completata, l'integrazione darebbe vita al terzo gruppo bancario italiano, provocando un rialzo del titolo BPM in Borsa e aprendo un confronto sugli equilibri finanziari nazionali.",
   "more": [
    "Il settore bancario italiano ha vissuto negli ultimi anni una progressiva concentrazione attorno a grandi poli creditizi nazionali. L'aggregazione tra un istituto italiano e un gruppo estero richiede valutazioni attente sulla contendibilità del mercato, sull'erogazione del credito a famiglie e imprese e sul ruolo delle autorità di vigilanza e del governo."
   ],
