   "id": "zbf04cb6c",
   "sez": "musica",
   "titolo": "Gli Angine de Poitrine ospitano sul palco un terzo musicista al triangolo",
   "orig": "Angine de Poitrine, spunta un terzo “alieno”: suona il triangolo su un brano inedito. Guarda il video",
   "lead": "Il duo musicale canadese Angine de Poitrine si è trasformato in trio durante il concerto tenuto il 5 novembre alla sala History di Toronto. La formazione ha accolto a sorpresa sul palco un terzo personaggio misterioso, vestito con il medesimo abito a pois caratteristico dei due musicisti Khn e Klek. Il nuovo arrivato ha accompagnato il gruppo suonando il triangolo durante l'esecuzione dal vivo di un brano inedito, ancora privo di titolo ufficiale, suscitando la curiosità del pubblico presente e dei fan del gruppo.",
   "more": [
    "Nel panorama della musica indipendente ed elettronica contemporanea, l'uso di maschere, costumi e identità fittizie è una scelta espressiva utilizzata per mantenere l'anonimato e focalizzare l'attenzione dello spettatore sull'esperienza visiva e concettuale della performance, superando la tradizionale dimensione del divismo musicale."
   ],
