   "sez": "ingegneria",
   "titolo": "Sony ripropone le storiche cuffie del Walkman con la versione MDR-3R",
   "orig": "Sony revives classic Walkman headphones as MDR-3R",
   "lead": "La società giapponese Sony punta sulla nostalgia degli anni Ottanta presentando il remake delle storiche cuffie originali del Walkman, ribattezzate MDR-3R. Il nuovo modello riprende le linee di quelle lanciate per la prima volta nel 1979, conservando le spugnette colorate intercambiabili e la struttura a filo, ma introducendo aggiornamenti tecnologici moderni come la porta USB-C per la compatibilità con gli smartphone e un microfono integrato. L'iniziativa intercetta il ritorno d'interesse per gli accessori cablati tra i giovani anche grazie a una partnership commerciale.",
   "more": [
    "Il Walkman Sony, introdotto sul mercato nel 1979, ha rivoluzionato il consumo musicale globale permettendo l'ascolto individuale e in mobilità delle audiocassette. La riscoperta degli accessori cablati riflette un fenomeno di consumo che unisce il design retrò alla ricerca di connessioni audio stabili e prive di batterie da ricaricare."
   ],
