   "id": "zab2b6726",
   "sez": "economia",
   "titolo": "Crollano gli utili dello studio di architettura britannico Feilden Clegg Bradley Studios",
   "orig": "FCBS profit nearly halves as turnover drops for third year running",
   "lead": "Lo studio di architettura britannico Feilden Clegg Bradley Studios ha registrato una riduzione del quarantacinque per cento dei propri profitti al lordo delle imposte. La flessione dei guadagni si inserisce in una fase di difficoltà economica più ampia per l'azienda, che vede il proprio fatturato calare per il terzo anno consecutivo, segnalando una contrazione duratura delle attività nel comparto professionale dell'edilizia e della progettazione nel Regno Unito. Lo riferisce The Architects' Journal.",
   "more": [
    "Il settore dei servizi di architettura e ingegneria è fortemente legato all'andamento dell'industria delle costruzioni e agli investimenti immobiliari. Aumenti nei costi delle materie prime, tassi d'interesse bancari più rigidi e il rallentamento dei cantieri privati e pubblici portano spesso a una riduzione delle commesse e dei margini di guadagno degli studi di progettazione."
   ],
