   "id": "z2180ef5f",
   "sez": "sport",
   "titolo": "Il giapponese Kozo Tashima sfida Gianni Infantino per la presidenza della FIFA",
   "orig": "Japanese challenger Tashima rates chances of unseating Fifa head Infantino at 20%-30%",
   "lead": "Il presidente onorario della federcalcio giapponese, Kozo Tashima, ha ufficializzato la propria candidatura per l'elezione presidenziale della FIFA prevista per il prossimo anno, diventando il primo dirigente nipponico a correre per la carica di vertice del calcio mondiale. L'ex calciatore sessantottenne, membro del consiglio direttivo della FIFA dal 2015, ha individuato nei meccanismi di governance il principale problema dell'organismo internazionale, stimando tra il venti e il trenta per cento le probabilità di sconfiggere il presidente uscente Gianni Infantino.",
   "more": [
    "La FIFA governa il calcio a livello planetario attraverso assemblee in cui ciascuna delle oltre duecento federazioni nazionali affiliate dispone di un voto. Le campagne per la leadership dell'ente si concentrano tipicamente su riforme della trasparenza amministrativa, redistribuzione dei proventi commerciali e modifiche ai formati delle competizioni internazionali."
   ],
