   "id": "zd0d50d89",
   "sez": "ambiente",
   "titolo": "Si apre la COP31 tra le tensioni sui fondi e l'impatto degli eventi climatici estremi",
   "orig": "COP31 opens with leaders under pressure to tackle climate crisis",
   "lead": "I negoziati della conferenza sul clima COP31 si sono aperti all'insegna delle forti pressioni sui capi di Stato e di governo, chiamati a intensificare le misure contro il riscaldamento del pianeta. I lavori sono iniziati con accesi confronti sulle risorse finanziarie destinate all'ambiente, mentre il segretario generale dell'ONU ha intimato ai leader mondiali di affrontare la crisi con serietà, dopo un anno segnato da ondate di calore in Europa, incendi devastanti in Indonesia e alluvioni disastrose in Nepal alimentate da El Niño.",
   "more": [
    "Il fenomeno di El Niño consiste in un riscaldamento ciclico e anomalo delle acque superficiali dell'oceano Pacifico centro-meridionale, capace di alterare la circolazione atmosferica su scala globale. La sua presenza tende ad amplificare le temperature medie planetarie e a intensificare episodi meteorologici estremi come siccità prolungate e precipitazioni torrenziali."
   ],
