   "id": "z595f2f3e",
   "sez": "ingegneria",
   "titolo": "Il padiglione statunitense alla Biennale Architettura 2027 celebrerà i costruttori",
   "orig": "\"Earth Craft\" at the U.S. Pavilion Will Trace the Work of Builders at the 2027 Venice Architecture Biennale",
   "lead": "La partecipazione degli Stati Uniti alla ventesima Mostra Internazionale di Architettura della Biennale di Venezia sarà dedicata al tema «Earth Craft». L'esposizione, commissionata e curata da una squadra della scuola di architettura dell'Università di Miami sotto la guida del professor Germane Barnes, si propone di esplorare il legame profondo tra l'architettura nazionale, i paesaggi e le figure umane che li plasmano, celebrando il lavoro concreto degli artigiani e dei costruttori che danno forma materiale agli edifici.",
   "more": [
    "La Biennale di Architettura di Venezia rappresenta una delle manifestazioni internazionali più prestigiose dedicate alla progettazione urbana e architettonica. I padiglioni nazionali ospitati ai Giardini e all'Arsenale espongono installazioni e visioni che interpretano temi sociali, ambientali e tecnologici attraverso il linguaggio della costruzione."
   ],
