   "id": "z0bfaf70b",
   "sez": "salute",
   "titolo": "In Nebraska le regole sui requisiti lavorativi di Medicaid tolgono la copertura a un malato",
   "orig": "Nebraska rushed Medicaid work rules. Then a cancer patient was told he'd lost coverage",
   "lead": "In Nebraska l'introduzione accelerata delle nuove norme che subordinano l'accesso a Medicaid allo svolgimento di un'attività lavorativa ha provocato forti polemiche, dopo che a un paziente oncologico è stata revocata la copertura sanitaria. Ambulatori medici e organizzazioni a tutela dei residenti a basso reddito denunciano che l'attuazione di tali vincoli è costellata di malfunzionamenti procedurali, con il rischio di privare dell'assistenza medica essenziale persone affette da gravi patologie. Lo riferisce NPR.",
   "more": [
    "Negli Stati Uniti il programma Medicaid, finanziato congiuntamente dal governo federale e dai singoli Stati, fornisce assistenza sanitaria alle fasce di popolazione a basso reddito. Alcune amministrazioni statali hanno promosso l'introduzione di obblighi di lavoro o di formazione come condizione per mantenere i benefici, sollevando critiche su possibili esclusioni burocratiche."
   ],
