   "id": "zb272296f",
   "sez": "italia",
   "titolo": "Tajani sollecita una strategia comune del G7 per fronteggiare gli attacchi hacker",
   "orig": "Tajani: G7 si coordini contro hacker",
   "lead": "Il ministro degli Esteri italiano Antonio Tajani ha chiesto un coordinamento rafforzato tra i Paesi membri del G7 per contrastare le minacce cibernetiche. Di fronte a quello che ha definito un attacco generale contro i sistemi e le infrastrutture informatiche, il capo della diplomazia ha esortato tutti i partner internazionali a collaborare attivamente attraverso lo scambio di informazioni e la messa a punto di difese condivise contro le azioni degli hacker ostili. Lo riferisce Rai News.",
   "more": [
    "Il vertice del G7 riunisce le principali economie avanzate, tra cui Italia, Francia, Germania, Regno Unito, Stati Uniti, Canada e Giappone, assieme all'Unione Europea. Negli ultimi anni la cybersicurezza è diventata prioritaria nell'agenda del gruppo per tutelare banche dati, reti energetiche e servizi pubblici essenziali."
   ],
