   "id": "zdc86477b",
   "sez": "cultura",
   "titolo": "Una mostra al museo del palazzo di Wangduechhoeling celebra la difesa del Bhutan",
   "orig": "New exhibition at Wangduechhoeling Palace Museum honours Bhutan’s Kings and warriors",
   "lead": "Una nuova esposizione museale allestita presso il centro culturale del palazzo di Wangduechhoeling, nel distretto bhutanese di Bumthang, rende omaggio al coraggio dei guerrieri locali e alla visione storica dei sovrani del regno. La mostra, intitolata «Armi, armature e la difesa di una nazione», è stata formalmente inaugurata dalle autorità reali ed espone antiche armi e protezioni militari per raccontare l'evoluzione delle strategie difensive del Paese nel corso dei secoli. Lo riferisce Bhutan Broadcasting Service.",
   "more": [
    "I palazzi storici e le fortezze del Bhutan, noti come dzong, hanno costituito per secoli il centro del potere spirituale, politico e militare del Paese. La conservazione museale degli apparati difensivi tradizionali permette di valorizzare l'identità nazionale e le tecniche artigianali di forgiatura dei metalli diffuse nell'area himalayana."
   ],
