   "id": "z9a3ed4e0",
   "sez": "musica",
   "titolo": "Fiona Apple pubblica una cover di Revolution a supporto di Medici Senza Frontiere",
   "orig": "Fiona Apple torna con “Revolution”: una canzone di protesta per aiutare Medici Senza Frontiere – Guarda il video",
   "lead": "La cantautrice statunitense Fiona Apple è tornata sulle scene musicali incidendo una propria reinterpretazione di «Revolution», celebre canzone di protesta pubblicata nel 1968 dalla formazione Mother Earth. Il pezzo è stato registrato insieme ai Bolt Cutters e sarà incluso nell'album benefico «Right Now», prodotto da Dougie Bowne. La musicista ha reso noto che l'intero ricavato ottenuto dalle vendite e dallo streaming della traccia sarà devoluto a sostegno dell'organizzazione umanitaria Medici Senza Frontiere. Lo riferisce OndaRock.",
   "more": [
    "Medici Senza Frontiere è una delle più note organizzazioni non governative internazionali impegnate nel soccorso sanitario di emergenza e nell'assistenza medica in zone di guerra, epidemie e disastri naturali. Il coinvolgimento di musicisti celebri rappresenta un canale frequente di raccolta fondi e sensibilizzazione dell'opinione pubblica su crisi umanitarie."
   ],
