   "id": "z188613d5",
   "sez": "economia",
   "titolo": "In Tanzania donne e giovani colgono le nuove opportunità del settore minerario a Tanga",
   "orig": "Tanga youth, women tap into growing mining opportunities",
   "lead": "Nella regione di Tanga, in Tanzania, un numero crescente di donne e giovani si sta inserendo nella filiera economica legata all'estrazione mineraria. Le autorità locali guardano alla ricchezza del sottosuolo non soltanto per il valore dei minerali e delle pietre preziose, ma come motore per attrarre investimenti, generare posti di lavoro e stimolare una rete di attività correlate capaci di rafforzare l'economia nazionale e favorire una trasformazione sociale sul territorio. Lo riferisce Daily News.",
   "more": [
    "L'Africa orientale custodisce riserve rilevanti di minerali critici, pietre preziose e metalli industriali. La partecipazione di cooperative giovanili e femminili all'attività estrattiva su piccola scala è considerata fondamentale dagli organismi di sviluppo per contrastare la disoccupazione e ridurre le disuguaglianze economiche nelle comunità rurali."
   ],
