   "id": "zb0e112f3",
   "sez": "salute",
   "titolo": "In Tanzania avanza la costruzione della fabbrica di presidi medici a Mloganzila",
   "orig": "Tanzania sees good progress in the construction of medical products factory at Mloganzila industria Park",
   "lead": "In Tanzania procedono secondo i piani i lavori per la realizzazione del polo produttivo di articoli medici all'interno del parco industriale di Mloganzila, a Dar es Salaam. La task force nazionale incaricata di accelerare gli investimenti nel comparto manifatturiero sanitario ha espresso soddisfazione per lo stato di avanzamento del cantiere, confermando che l'avvio della produzione locale di circa il sessanta per cento delle attrezzature mediche previste è programmato per il maggio del 2027. Lo riferisce Daily News.",
   "more": [
    "Molti Paesi africani dipendono quasi interamente dall'estero per l'approvvigionamento di farmaci e dispositivi sanitari monouso, come siringhe, guanti e camici. La costruzione di stabilimenti industriali dedicati mira ad accrescere l'autosufficienza nazionale, diminuire i costi di importazione e proteggere le strutture sanitarie da interruzioni nelle catene logistiche globali."
   ],
