   "id": "z1a2b64d6",
   "sez": "tech",
   "titolo": "La Norvegia frena l'espansione dei centri dati per tutelare la rete elettrica",
   "orig": "Norway reins in data centre industry amid AI boom",
   "lead": "Il governo della Norvegia ha annunciato l'intenzione di porre un freno alla rapida proliferazione dei centri di elaborazione dati nel Paese nordico, spinta dal boom globale dell'intelligenza artificiale. Sebbene la nazione produca ingenti quantità di energia da fonti rinnovabili, le autorità temono che l'enorme fabbisogno energetico richiesto dai nuovi impianti possa generare deficit nella rete e causare un forte rincaro dei prezzi dell'elettricità per cittadini e imprese nei prossimi anni.",
   "more": [
    "I data center necessari per addestrare ed eseguire modelli avanzati di intelligenza artificiale assorbono enormi quantità di energia elettrica per i calcoli e per il raffreddamento dei server. I Paesi nordici, storicamente attrattivi per il clima freddo e l'idroelettrico a basso costo, si trovano ora a bilanciare lo sviluppo tecnologico con la tenuta delle reti nazionali."
   ],
