   "id": "zcaa380a0",
   "sez": "italia",
   "titolo": "Roma, invasione di uccelli nel Municipio III: strade e cassonetti coperti di guano",
   "orig": "Roma, invasione di uccelli nel Municipio III: in viale Jonio strade e cassonetti ricoperti di guano. I residenti: «In pochi giorni 50 euro per l'autolavaggio»",
   "lead": "Nel Municipio III di Roma, lungo viale Jonio, la presenza massiccia di uccelli sta causando disagi rilevanti alla circolazione e alla vivibilità del quartiere. Domenica 8 novembre le carreggiate, i marciapiedi e i cassonetti dei rifiuti sono stati ricoperti da ingenti quantità di guano, spingendo molti residenti a evitare la sosta delle automobili sotto le alberature. I cittadini lamentano le condizioni igieniche precarie dell'area e denunciano spese frequenti, fino a cinquanta euro nell'arco di pochi giorni, per il lavaggio dei veicoli. Lo riferisce Il Messaggero – Roma.",
   "more": [
    "Nelle grandi aree urbane la presenza periodica di storni e altri volatili crea complicazioni legate alla gestione della pulizia stradale e alla manutenzione del verde. Il guano accumulato può rendere scivoloso l'asfalto per pedoni e veicoli a due ruote, oltre a danneggiare le carrozzerie delle automobili, richiedendo interventi straordinari di lavaggio da parte dei servizi municipali."
   ],
