   "sez": "economia",
   "titolo": "Trimestre record per Unicredit: l'utile sale a 3,2 miliardi di euro",
   "orig": "Per Unicredit il miglior trimestre di sempre. Orcel: “In Italia cresciamo forte senza acquisizioni”",
   "lead": "Unicredit ha registrato il miglior trimestre della propria storia con un utile netto pari a 3,2 miliardi di euro, segnando un incremento del 24 per cento. Nei primi nove mesi dell'anno il risultato complessivo ha raggiunto i 9,4 miliardi. L'amministratore delegato Andrea Orcel ha spiegato che nel mercato italiano l'istituto è cresciuto dell'1,3 per cento e punta a raggiungere il 15 per cento entro pochi trimestri senza ricorrere ad acquisizioni, mentre sul fronte estero è attesa entro fine novembre l'evoluzione relativa all'operazione su Commerzbank.",
   "more": [
    "Il settore bancario europeo sta attraversando una fase di forte redditività favorita dal livello dei tassi d'interesse fissati dalla Banca Centrale Europea, che ha sostenuto il margine d'interesse degli istituti di credito. Parallelamente, si moltiplicano le discussioni su possibili aggregazioni e operazioni transfrontaliere per creare gruppi bancari di maggiori dimensioni all'interno dell'Unione europea."
   ],
