   "id": "z131289e7",
   "sez": "economia",
   "titolo": "Repubblica Ceca, disoccupazione stabile al 5% e piano di tagli ai sussidi",
   "orig": "Czech unemployment remains at five percent for fourth consecutive month",
   "lead": "In Repubblica Ceca il tasso di disoccupazione si è attestato al cinque per cento per il quarto mese consecutivo, confermando una sostanziale stabilità sul mercato del lavoro nazionale. Parallelamente, il governo di Praga sta valutando l'introduzione di una riforma volta a ridurre l'entità dei sussidi di disoccupazione a partire dal gennaio 2027. La proposta prevede un abbassamento delle erogazioni iniziali e dei massimali previsti per gli assegni, una misura che potrebbe coinvolgere i lavoratori che perderanno il posto di lavoro a partire dal prossimo anno.",
   "more": [
    "I regimi di protezione sociale nei Paesi dell'Unione europea bilanciano il sostegno al reddito con incentivi al rapido reinserimento lavorativo. Una revisione al ribasso dei massimali e dei contributi per l'indennità mira solitamente a contenere la spesa pubblica e a stimolare la ricerca attiva di un nuovo impiego, benché susciti spesso dibattiti tra parti sociali e istituzioni."
   ],
