   "id": "z5fc9299f",
   "sez": "cucina",
   "titolo": "Kfc approda sulle piste da sci: polemiche per le aperture a Madonna di Campiglio e Cortina",
   "orig": "Kfc porta pollo fritto e fast food sulle piste da sci. Farinetti: «Non c’entrano nulla»",
   "lead": "La catena di fast food statunitense Kfc ha annunciato l'apertura dal 5 dicembre di due ristoranti stagionali sulle Dolomiti, a Cortina d'Ampezzo e a Madonna di Campiglio, con un locale situato a oltre 2.100 metri di altitudine. L'iniziativa ha suscitato reazioni contrastanti nel mondo della ristorazione e dell'enogastronomia alpina. Tra i critici dell'operazione figura Oscar Farinetti, il quale ha espresso netta contrarietà sostenendo che il pollo fritto industriale non abbia alcun legame con la tradizione e l'identità dell'offerta montana sulle piste da sci.",
   "more": [
    "Le località montane d'alta quota sono tradizionalmente legate alla ristorazione tipica basata su piatti regionali come polenta, formaggi e carni locali. L'ingresso delle grandi catene globali della ristorazione rapida nei comprensori alpini riflette una strategia commerciale di forte visibilità turistica durante i grandi eventi invernali, attirando però critiche sulla valorizzazione del patrimonio culinario locale."
   ],
