   "titolo": "Francia, il campione di judo Teddy Riner annuncia la candidatura all'Eliseo per il 2027",
   "orig": "🔴 Présidentielle 2027 : la star française du judo Teddy Riner annonce sa candidature",
   "lead": "Il tre volte campione olimpico individuale di judo Teddy Riner ha annunciato la propria candidatura alle elezioni presidenziali francesi del 2027, dichiarando di voler unire il Paese e spinto dal malcontento sociale. L'atleta, che si definisce non collocato né a destra né a sinistra, inizierà la campagna elettorale a breve senza interrompere l'attività sportiva. L'annuncio giunge in una fase di forte tensione sindacale sui salari e mentre i sondaggi indicano la crescita di Marine Le Pen e Jean-Luc Mélenchon a scapito dei candidati tradizionali.",
   "more": [
    "L'ingresso di figure del mondo dello sport o della società civile nella competizione per l'Eliseo rappresenta un fenomeno non insolito nelle democrazie occidentali, dove cresce la sfiducia nei partiti tradizionali. Il sistema elettorale presidenziale francese prevede un doppio turno a suffragio universale diretto per l'elezione del capo dello Stato."
   ],
