   "id": "zb3965cf3",
   "sez": "ambiente",
   "titolo": "Isole Salomone, forte scossa di terremoto di magnitudo 6.4 senza allerta tsunami",
   "orig": "Fuerte sismo de magnitud 6,4 sacude las Islas Salomón en la noche de este domingo 8 de noviembre: esto es lo que se sabe",
   "lead": "Un potente terremoto di magnitudo 6.4 sulla scala Richter ha scosso l'arcipelago delle Isole Salomone nella serata di domenica 8 novembre. L'evento sismico è stato localizzato a circa trenta chilometri a sud-ovest della cittadina di Lata, capoluogo della provincia orientale di Temotu, a una profondità stimata in diciassette chilometri nel sottosuolo dell'Oceano Pacifico. Nonostante l'intensità della scossa, i centri sismologici e le autorità di protezione civile non hanno diramato alcuna allerta per rischio di onde anomale o tsunami lungo le coste limitrofe.",
   "more": [
    "L'area del Pacifico sud-occidentale si trova lungo la cosiddetta Cintura di fuoco, una delle zone tettonicamente più attive del pianeta dove la collisione tra placche genera frequentemente forti terremoti ed eruzioni vulcaniche. Gli ipocentri a bassa profondità possono provocare forti scuotimenti in superficie anche in assenza di maremoti."
   ],
