   "id": "z633d1296",
   "sez": "dibattito",
   "titolo": "Paesi Bassi, l'organismo per i diritti denuncia la sorveglianza statale sulle manifestazioni",
   "orig": "'Mensenrechten onder druk door overheidstoezicht rond demonstraties'",
   "lead": "Nei Paesi Bassi il College voor de Rechten van de Mens, organismo nazionale indipendente per i diritti umani, ha denunciato una crescente raccolta di informazioni da parte dello Stato sulle manifestazioni pubbliche. Nel rapporto annuale, il presidente dell'ente Rick Lawson sottolinea che a chi organizza cortei vengono chiesti dati anagrafici, residenza e profili social, avvertendo che tale vigilanza rischia di minare la fiducia nelle istituzioni e comprimere il diritto di dissenso. Le autorità motivano invece le richieste con l'esigenza di pianificare la sicurezza pubblica e prevenire disordini.",
   "more": [
    "La libertà di riunione pacifica e di manifestazione è sancita dalla Costituzione olandese e dalle convenzioni internazionali sui diritti umani. Il confine tra le misure preventive adottate dalle forze dell'ordine per tutelare l'ordine pubblico e la protezione della riservatezza dei manifestanti è oggetto di periodiche discussioni legali in Europa, soprattutto in relazione all'uso di archivi digitali e monitoraggio telematico."
   ],
