   "id": "ze7dd81fc",
   "sez": "mondo",
   "titolo": "Stati Uniti, l'opposizione democratica alla Camera chiede l'impeachment per Pete Hegseth",
   "orig": "US top Democrat backs impeachment of Pete Hegseth",
   "lead": "Ai vertici del Partito Democratico alla Camera dei Rappresentanti degli Stati Uniti è stato espresso un esplicito sostegno alla messa in stato d'accusa di Pete Hegseth. L'esponente democratico ha dichiarato che il segretario deve lasciare l'incarico, indicandolo tra i principali responsabili per le tensioni legate alla guerra in corso con l'Iran e per il pesante incremento dei prezzi del carburante che grava sui cittadini americani. L'iniziativa parlamentare mira ad aprire un procedimento formale di revoca dell'incarico federale.",
   "more": [
    "L'impeachment è lo strumento costituzionale con cui la Camera dei Rappresentanti può incriminare i funzionari dell'esecutivo o il presidente per gravi mancanze o violazioni della legge, demandando al Senato il successivo processo politico. In un Congresso diviso, tali iniziative riflettono un aspro scontro politico sulle scelte militari ed economiche."
   ],
