   "id": "z49993e17",
   "sez": "economia",
   "titolo": "Cina, prorogata a gennaio la sospensione dei controlli sulle terre rare",
   "orig": "China extends suspension of new rare earth controls until January",
   "lead": "Il governo cinese ha annunciato una proroga di due mesi, fino al mese di gennaio, per la sospensione dei nuovi controlli sulle esportazioni di terre rare, la cui scadenza era originariamente prevista entro il mese di novembre. La decisione commerciale giunge mentre le industrie manifatturiere cinesi stanno testando nuove applicazioni industriali avanzate legate a questi materiali, tra cui speciali gomme ad alte prestazioni per il settore dei veicoli elettrici e degli pneumatici pesanti, che sui mercati internazionali registrano prezzi superiori rispetto ai prodotti sintetici convenzionali.",
   "more": [
    "Le terre rare comprendono un gruppo di diciassette elementi chimici indispensabili per l'industria ad alta tecnologia, dai motori elettrici all'elettronica di consumo e alla difesa. La Cina detiene una posizione dominante nell'estrazione e nella raffinazione globale, rendendo le proprie decisioni sulle quote e sui dazi decisive per le catene industriali mondiali."
   ],
