   "sez": "economia",
   "titolo": "Georgia, ispettori russi completano i controlli sui laboratori per l'export di frutta",
   "orig": "Russia’s Rosselkhoznadzor Delegation Concludes Inspection Visit to Georgia",
   "lead": "Una delegazione dell'agenzia federale russa per la vigilanza veterinaria e fitosanitaria, il Rosselkhoznadzor, ha concluso una missione ispettiva in Georgia svolta tra il 2 e il 6 novembre su invito dell'Agenzia nazionale per gli alimenti locale. Gli esperti di Mosca hanno condotto verifiche nei laboratori di analisi statali e in cinque impianti di coltivazione e stoccaggio della frutta a Gori, con l'obiettivo di esaminare i protocolli di certificazione fitosanitaria per le esportazioni verso la Russia, in una fase segnata da divieti di importazione sulle bevande georgiane.",
   "more": [
    "Le misure sanitarie e fitosanitarie vengono spesso utilizzate nelle relazioni commerciali tra i Paesi dell'area ex sovietica come strumenti tecnici che risentono delle oscillazioni diplomatiche. La Russia costituisce storicamente un mercato rilevante per i prodotti agricoli della Georgia, dall'ortofrutta ai prodotti vitivinicoli."
   ],
