   "id": "z3718fe6c",
   "sez": "ambiente",
   "titolo": "Meteo globale, allarme dell'Onu per mesi di caldo eccezionale per il rafforzamento di El Niño",
   "orig": "World faces months of exceptional heat as El Nino intensifies, UN warns",
   "lead": "Le Nazioni Unite hanno lanciato un allarme globale sul rischio di mesi caratterizzati da temperature eccezionalmente elevate a causa della progressiva intensificazione del fenomeno climatico El Niño. Secondo le stime dell'ONU, il fenomeno meteorologico potrebbe toccare un picco di intensità record entro il prossimo mese di dicembre e proseguire i suoi effetti sul clima terrestre almeno fino a febbraio 2027. Nei territori dell'Oceano Pacifico, tra cui l'arcipelago di Tonga, i servizi meteorologici hanno già invitato la popolazione a razionare e conservare le scorte d'acqua a causa della siccità.",
   "more": [
    "El Niño è un fenomeno periodico provocato dal riscaldamento anomalo delle acque superficiali dell'Oceano Pacifico equatoriale orientale. La sua insorgenza altera i regimi pluviometrici e le temperature su vasta scala, favorendo ondate di calore estremo, alluvioni in alcune regioni costiere e intense siccità in altre parti del pianeta."
   ],
