   "sez": "sport",
   "titolo": "Kazakistan, il presidente Tokayev premia i medagliati dei Giochi Asiatici verso Los Angeles 2028",
   "orig": "Tokayev Honors Asian Games Medalists, Calls for Stronger Olympic Preparations",
   "lead": "Il presidente del Kazakistan Kassym-Jomart Tokayev ha ricevuto e premiato diciannove atleti nazionali che hanno conquistato medaglie nel corso della ventesima edizione dei Giochi Asiatici e dei quinti Giochi Para-Asiatici. Durante la cerimonia solenne ad Astana, il capo dello Stato ha elogiato i risultati ottenuti nelle rassegne continentali sottolineando il valore educativo per le giovani generazioni e ha invitato le federazioni a intensificare i programmi di allenamento in vista delle prossime Olimpiadi di Los Angeles nel 2028.",
   "more": [
    "I Giochi Asiatici rappresentano il principale evento sportivo multidisciplinare dell'Asia, organizzato a cadenza quadriennale sotto l'egida del Consiglio Olimpico d'Asia. Nelle repubbliche centroasiatiche i successi sportivi internazionali godono di un consistente sostegno governativo per favorire il prestigio nazionale e la promozione dell'attività agonistica giovanile."
   ],
